// Rasterize the owner's official vector paths for email-client compatibility.
// This email edition uses pale lavender in place of the website's lime accent.
import { readFile, writeFile } from 'node:fs/promises'
import { createHash } from 'node:crypto'
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import sharp from 'sharp'

const root = fileURLToPath(new URL('../', import.meta.url))
const assets = [
  ['wordmark', 'rayab_wordmark.svg', 864, 'rayab-wordmark@portfolio'],
  ['mark', 'rayab_icon.svg', 144, 'rayab-mark@portfolio'],
]
const output = [
  '// Generated by scripts/prepare-email-brand.mjs from the official Rayab SVGs.',
  '// Inline CID PNGs are bundled with the server. No external image URLs or filesystem reads.',
  'export const EMAIL_BRAND = {',
]
for (const [name, filename, width, cid] of assets) {
  const original = await readFile(path.join(root, 'public/brand/rayab', filename))
  const source = original
    .toString()
    .replaceAll('#dfff45', '#ded4ff')
    .replaceAll('#fcfcfc', '#f7f6ed')
  const { data, info } = await sharp(Buffer.from(source), { density: 144 })
    .resize({ width })
    .flatten({ background: '#10110c' })
    .png({ compressionLevel: 9, palette: true, colours: 128 })
    .toBuffer({ resolveWithObject: true })
  const digest = createHash('sha256').update(original).digest('hex')
  output.push(
    `  ${name}: {`,
    `    // ${filename} SHA-256: ${digest}`,
    `    cid: '${cid}',`,
    `    width: ${info.width}, height: ${info.height},`,
    `    base64: '${data.toString('base64')}',`,
    '  },',
  )
  console.log(`${filename} → embedded ${info.width}×${info.height} PNG (${data.length} bytes)`)
}
output.push('} as const', '')
await writeFile(path.join(root, 'src/emails/brand-assets.generated.ts'), output.join('\n'))
